<?php
declare(strict_types=1);
namespace App\Entity\Suppliers;
use App\Entity\Common\Timestampable; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity,ORM\Table(name:'supplier_branches'),ORM\UniqueConstraint(name:'uniq_supplier_branch_code',columns:['supplier_id','code']),ORM\HasLifecycleCallbacks]
class SupplierBranch { use Timestampable; #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne,ORM\JoinColumn(name:'supplier_id',nullable:false,onDelete:'CASCADE')] private Supplier $supplier; #[ORM\Column(length:40)] private string $code; #[ORM\Column(length:160)] private string $name; #[ORM\Column(length:180,nullable:true)] private ?string $email=null; #[ORM\Column(type:'text',nullable:true)] private ?string $notes=null; #[ORM\Column(name:'is_main',options:['default'=>false])] private bool $isMain=false; #[ORM\Column(name:'is_active',options:['default'=>true])] private bool $isActive=true;
 public function __construct(Supplier $supplier,string $code,string $name){$this->supplier=$supplier;$this->setCode($code);$this->setName($name);$this->initializeTimestamps();} public function getId():?int{return $this->id;} public function getSupplier():Supplier{return $this->supplier;} public function getCode():string{return $this->code;} public function setCode(string $v):self{$this->code=strtoupper(trim($v));return $this;} public function getName():string{return $this->name;} public function setName(string $v):self{$this->name=trim($v);return $this;} public function getEmail():?string{return $this->email;} public function setEmail(?string $v):self{$v=trim((string)$v);$this->email=$v?strtolower($v):null;return $this;} public function getNotes():?string{return $this->notes;} public function setNotes(?string $v):self{$v=trim((string)$v);$this->notes=$v?:null;return $this;} public function isMain():bool{return $this->isMain;} public function setIsMain(bool $v):self{$this->isMain=$v;return $this;} public function isActive():bool{return $this->isActive;} public function setIsActive(bool $v):self{$this->isActive=$v;return $this;}
}
